package net.officefloor.hq.app.person;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.FetchType;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import jakarta.persistence.Version;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashSet;
import java.util.List;
import java.util.Objects;
import java.util.Set;
import net.officefloor.hq.app.claim.ClaimStatus;

/** A person on a sheet, with a name and dated grades (A, B or C), who may be retired from a date
 * and may be put on hold. */
@Entity
@Table(name = "person")
public class Person {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "name", nullable = false)
    private String name;

    /** The grades recorded for the person, each in force from its from-date; the first has none. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_grade", joinColumns = @JoinColumn(name = "person_id"))
    private List<PersonGrade> grades = new ArrayList<>();

    /** The date the person is retired from; null while they are not retired. */
    @Column(name = "retired_from")
    private LocalDate retiredFrom;

    /** Whether the person is on hold: while held, their open claims count in no live total. */
    @Column(name = "held", nullable = false)
    private boolean held;

    /** The ids of the other people on the sheet this person names as their patrons. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_patron", joinColumns = @JoinColumn(name = "person_id"))
    @Column(name = "patron_id", nullable = false)
    private Set<Long> patronIds = new HashSet<>();

    /** Raised each time the person is saved. */
    @Version
    @Column(name = "version", nullable = false)
    private long version;

    protected Person() {
    }

    public Person(String sheetId, String name, String grade) {
        this.sheetId = sheetId;
        this.name = name;
        this.grades.add(new PersonGrade(null, grade));
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }

    public void setName(String name) {
        this.name = name;
    }

    /** The grades recorded, from the first (from the beginning of time) to the latest from-date. */
    public List<PersonGrade> getGrades() {
        return grades.stream()
                .sorted(Comparator.comparing(PersonGrade::getFrom, Comparator.nullsFirst(Comparator.naturalOrder())))
                .toList();
    }

    /** The grade in force on a date: the one with the latest from-date on or before it. */
    public String gradeOn(LocalDate date) {
        return grades.stream()
                .filter(g -> g.getFrom() == null || !g.getFrom().isAfter(date))
                .max(Comparator.comparing(PersonGrade::getFrom, Comparator.nullsFirst(Comparator.naturalOrder())))
                .map(PersonGrade::getGrade)
                .orElse(null);
    }

    /** Record a grade from a date, replacing one already recorded from that date. */
    public void setGradeFrom(LocalDate from, String grade) {
        grades.removeIf(g -> Objects.equals(g.getFrom(), from));
        grades.add(new PersonGrade(from, grade));
    }

    public LocalDate getRetiredFrom() {
        return retiredFrom;
    }

    public void setRetiredFrom(LocalDate retiredFrom) {
        this.retiredFrom = retiredFrom;
    }

    /** Whether a claim dated on this date is refused: it is after the person's retirement date. */
    public boolean retiredOn(LocalDate date) {
        return retiredFrom != null && date.isAfter(retiredFrom);
    }

    public boolean isHeld() {
        return held;
    }

    public void setHeld(boolean held) {
        this.held = held;
    }

    /** Whether a claim of this person in this status counts toward the totals: an open one not while held. */
    public boolean counts(ClaimStatus status) {
        return status.counts() && !(held && status.isOpen());
    }

    public Set<Long> getPatronIds() {
        return patronIds;
    }

    public long getVersion() {
        return version;
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Optional;
import java.util.Set;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.dao.OptimisticLockingFailureException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/**
 * The people kept on a sheet, in the order they were added. A name is stored without surrounding
 * spaces and is unique on its sheet regardless of case. An edit is made from a version of the
 * person; once someone else has saved the person since, it is refused.
 */
@Service
public class PersonService {

    private static final int MAX_NAME = 100;
    private static final Set<String> GRADES = Set.of("A", "B", "C");

    private final PersonRepository people;
    private final SheetService sheets;
    private final Audit audit;

    public PersonService(PersonRepository people, SheetService sheets, Audit audit) {
        this.people = people;
        this.sheets = sheets;
        this.audit = audit;
    }

    /** The sheet's today, the date the grade each person is listed with is in force on. */
    @Transactional(readOnly = true)
    public LocalDate today(String sheetId) {
        return sheets.today(sheetId);
    }

    @Transactional(readOnly = true)
    public List<Person> list(String sheetId) {
        return people.findBySheetIdOrderByIdAsc(sheetId);
    }

    @Transactional
    public Person add(String sheetId, String user, String name, String grade) {
        sheets.load(sheetId, user);
        String trimmed = name.trim();
        if (people.existsBySheetIdAndNameIgnoreCase(sheetId, trimmed)) {
            throw nameInUse();
        }
        Person person = people.save(new Person(sheetId, trimmed, grade));
        audit.change("PERSON_ADDED", sheetId, user, "name=" + person.getName(), "grade=" + grade);
        return person;
    }

    /** A line of an import that breaks a rule: its number (from 1) and why. */
    public record ImportError(int line, String message) {
    }

    /**
     * How many people an import added and how many existing ones it updated, or the lines that
     * stopped it (then nothing is changed).
     */
    public record ImportResult(int added, int updated, List<ImportError> errors) {
    }

    /**
     * Import people from lines of name,grade. Every line is checked first with the rules of the form;
     * a name repeated in the paste is compared like uniqueness on the sheet. If any line breaks a
     * rule nothing is changed; otherwise, in order, a name already on the sheet has its grade
     * recorded from the sheet's today and any other name is added. Blank lines are skipped.
     */
    @Transactional
    public ImportResult importPeople(String sheetId, String user, String text) {
        String[] lines = text.split("\\r?\\n", -1);
        List<ImportError> errors = new ArrayList<>();
        List<String[]> rows = new ArrayList<>();
        Set<String> seen = new HashSet<>();
        for (int i = 0; i < lines.length; i++) {
            String line = lines[i];
            if (line.isBlank()) {
                continue;
            }
            int number = i + 1;
            int comma = line.lastIndexOf(',');
            String name = (comma < 0 ? line : line.substring(0, comma)).trim();
            String grade = comma < 0 ? "" : line.substring(comma + 1).trim();
            String error = null;
            if (name.isEmpty()) {
                error = "Enter a name.";
            } else if (name.length() > MAX_NAME) {
                error = "The name is too long.";
            } else if (!GRADES.contains(grade)) {
                error = "The grade must be A, B or C.";
            } else if (!seen.add(name.toLowerCase(Locale.ROOT))) {
                error = "That name is repeated in the import.";
            }
            if (error != null) {
                errors.add(new ImportError(number, error));
            } else {
                rows.add(new String[] {name, grade});
            }
        }
        if (!errors.isEmpty()) {
            return new ImportResult(0, 0, errors);
        }
        LocalDate today = null;
        if (!rows.isEmpty()) {
            sheets.load(sheetId, user);
            today = sheets.today(sheetId);
        }
        int added = 0;
        int updated = 0;
        for (String[] row : rows) {
            Optional<Person> existing = people.findFirstBySheetIdAndNameIgnoreCase(sheetId, row[0]);
            if (existing.isPresent()) {
                Person person = existing.get();
                person.setGradeFrom(today, row[1]);
                person = people.saveAndFlush(person);
                audit.change("PERSON_EDITED", sheetId, user, "name=" + person.getName(), "grade=" + row[1]);
                updated++;
            } else {
                Person person = people.save(new Person(sheetId, row[0], row[1]));
                audit.change("PERSON_ADDED", sheetId, user, "name=" + person.getName(), "grade=" + row[1]);
                added++;
            }
        }
        return new ImportResult(added, updated, List.of());
    }

    /**
     * Save a person's name, and record the grade from a date (the sheet's today when none is given),
     * keeping the grades already recorded; a grade already recorded from that date is replaced.
     */
    @Transactional
    public Person update(String sheetId, String user, Long personId, long version, String name, String grade,
            LocalDate gradeFrom) {
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        if (person.getVersion() != version) {
            throw changedMeanwhile();
        }
        String trimmed = name.trim();
        if (people.existsBySheetIdAndNameIgnoreCaseAndIdNot(sheetId, trimmed, personId)) {
            throw nameInUse();
        }
        person.setName(trimmed);
        person.setGradeFrom(gradeFrom != null ? gradeFrom : sheets.today(sheetId), grade);
        try {
            person = people.saveAndFlush(person);
        } catch (OptimisticLockingFailureException e) {
            throw changedMeanwhile();
        }
        audit.change("PERSON_EDITED", sheetId, user, "name=" + person.getName(), "grade=" + grade);
        return person;
    }

    /**
     * Retire a person from a date (the sheet's today when none is given). A person already retired is
     * refused (409); claims dated on or before the date stay allowed.
     */
    @Transactional
    public Person retire(String sheetId, String user, Long personId, LocalDate from) {
        // Lock the sheet, so a claim added at the same moment sees the retirement.
        sheets.lock(sheetId);
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        if (person.getRetiredFrom() != null) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "Person already retired");
        }
        person.setRetiredFrom(from != null ? from : sheets.today(sheetId));
        person = people.saveAndFlush(person);
        audit.change("PERSON_RETIRED", sheetId, user, "name=" + person.getName(), "from=" + person.getRetiredFrom());
        return person;
    }

    /**
     * Put a person on hold, or release them from it. Holding one already held, or releasing one not
     * held, is refused (409).
     */
    @Transactional
    public Person hold(String sheetId, String user, Long personId, boolean held) {
        // Lock the sheet, so a period closed at the same moment sees the hold.
        sheets.lock(sheetId);
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        if (person.isHeld() == held) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    held ? "Person already on hold" : "Person not on hold");
        }
        person.setHeld(held);
        person = people.saveAndFlush(person);
        audit.change(held ? "PERSON_HELD" : "PERSON_RELEASED", sheetId, user, "name=" + person.getName());
        return person;
    }

    /**
     * Name another person on the same sheet as one of this person's patrons. Naming themselves is
     * refused (422), and so is naming someone already a patron (409).
     */
    @Transactional
    public Person addPatron(String sheetId, String user, Long personId, Long patronId) {
        sheets.lock(sheetId);
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        Person patron = people.findByIdAndSheetId(patronId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such patron"));
        if (patron.getId().equals(person.getId())) {
            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY, "A person cannot be their own patron");
        }
        if (!person.getPatronIds().add(patron.getId())) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "Already a patron");
        }
        person = people.saveAndFlush(person);
        audit.change("PATRON_ADDED", sheetId, user, "name=" + person.getName(), "patron=" + patron.getName());
        return person;
    }

    private static ResponseStatusException changedMeanwhile() {
        return new ResponseStatusException(HttpStatus.PRECONDITION_FAILED, "Person changed since it was loaded");
    }

    private static ResponseStatusException nameInUse() {
        return new ResponseStatusException(HttpStatus.CONFLICT, "Name already in use");
    }
}
package net.officefloor.hq.app.person;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import java.util.List;
import org.springframework.http.HttpStatus;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

/** People on a sheet. The signed-in user's name is sent in the X-User header. */
@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}/people")
public class PersonController {

    /** A grade recorded for a person; from is null for the first one, in force from the beginning of time. */
    public record GradeView(LocalDate from, String grade) {
    }

    /**
     * The version is the one an edit sends back, so a save made from an out-of-date copy is refused.
     * The grade is the one in force on the sheet's today; grades are all those recorded, oldest first.
     */
    public record PersonView(Long id, String name, String grade, List<GradeView> grades, long version,
            LocalDate retiredFrom, boolean held, List<Long> patronIds) {
        static PersonView of(Person person, LocalDate today) {
            return new PersonView(person.getId(), person.getName(), person.gradeOn(today),
                    person.getGrades().stream().map(g -> new GradeView(g.getFrom(), g.getGrade())).toList(),
                    person.getVersion(), person.getRetiredFrom(), person.isHeld(),
                    person.getPatronIds().stream().sorted().toList());
        }
    }

    /** The name is stored trimmed; one that is empty or only spaces is refused. */
    public record PersonRequest(
            @NotBlank @Size(max = 100) String name,
            @NotNull @Pattern(regexp = "[ABC]") String grade) {
    }

    /** An edit carries the version of the person it was made from, and the date its grade applies from
     * (the sheet's today when none is given). */
    public record PersonUpdateRequest(
            @NotBlank @Size(max = 100) String name,
            @NotNull @Pattern(regexp = "[ABC]") String grade,
            LocalDate gradeFrom,
            @NotNull Long version) {
    }

    /** Retire a person from a date; a missing date is the sheet's today. */
    public record RetireRequest(LocalDate from) {
    }

    /** Name another person on the sheet as a patron. */
    public record PatronRequest(@NotNull Long patronId) {
    }

    /** Lines of name,grade pasted into the import box. */
    public record ImportRequest(@NotNull @Size(max = 100_000) String text) {
    }

    private final PersonService service;

    public PersonController(PersonService service) {
        this.service = service;
    }

    @GetMapping
    public List<PersonView> list(@PathVariable @NotBlank @Size(max = 100) String sheetId) {
        LocalDate today = service.today(sheetId.trim());
        return service.list(sheetId.trim()).stream().map(person -> PersonView.of(person, today)).toList();
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public PersonView add(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Validated PersonRequest request) {
        return view(sheetId, service.add(sheetId.trim(), user.trim(), request.name(), request.grade()));
    }

    @PutMapping("/{personId}")
    public PersonView update(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable Long personId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Validated PersonUpdateRequest request) {
        return view(sheetId, service.update(sheetId.trim(), user.trim(), personId, request.version(),
                request.name(), request.grade(), request.gradeFrom()));
    }

    @PostMapping("/{personId}/retire")
    public PersonView retire(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable Long personId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody RetireRequest request) {
        return view(sheetId, service.retire(sheetId.trim(), user.trim(), personId, request.from()));
    }

    @PostMapping("/{personId}/hold")
    public PersonView hold(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable Long personId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return view(sheetId, service.hold(sheetId.trim(), user.trim(), personId, true));
    }

    @PostMapping("/{personId}/release")
    public PersonView release(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable Long personId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user) {
        return view(sheetId, service.hold(sheetId.trim(), user.trim(), personId, false));
    }

    @PostMapping("/{personId}/patrons")
    public PersonView addPatron(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @PathVariable Long personId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Validated PatronRequest request) {
        return view(sheetId, service.addPatron(sheetId.trim(), user.trim(), personId, request.patronId()));
    }

    private PersonView view(String sheetId, Person person) {
        return PersonView.of(person, service.today(sheetId.trim()));
    }

    @PostMapping("/import")
    public PersonService.ImportResult importPeople(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @RequestBody @Validated ImportRequest request) {
        return service.importPeople(sheetId.trim(), user.trim(), request.text());
    }
}
